import type { StorageBackend, RedisStorageConfig } from '../types';
import { logger } from '../logger';

export class RedisStorage implements StorageBackend {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  private client: any = null;
  private keyPrefix: string;
  private ttl: number;
  private config: RedisStorageConfig;

  constructor(config: RedisStorageConfig) {
    this.config = config;
    this.keyPrefix = config.keyPrefix || 'hippocampus:memory:';
    this.ttl = config.ttl || 0;
  }

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  private async ensureClient(): Promise<any> {
    if (this.client) {
      return this.client;
    }

    const { createClient } = await import('redis');

    const host = this.config.host || process.env.REDIS_HOST || 'localhost';
    const port = this.config.port || parseInt(process.env.REDIS_PORT || '6379', 10);
    const password = this.config.password || process.env.REDIS_PASSWORD || undefined;
    const db = this.config.db ?? parseInt(process.env.REDIS_DB || '0', 10);

    this.client = createClient({
      socket: { host, port },
      password,
      database: db,
    });

    this.client.on('error', (err: Error) => {
      logger.error('Redis client error', { error: err.message });
    });

    await this.client.connect();
    logger.info('Redis storage initialized', { host, port, db, keyPrefix: this.keyPrefix });
    return this.client;
  }

  private key(ownerId: string): string {
    return `${this.keyPrefix}${ownerId}`;
  }

  async get(ownerId: string): Promise<string | null> {
    try {
      const client = await this.ensureClient();
      return await client.get(this.key(ownerId));
    } catch (error) {
      logger.error('Redis get failed', {
        ownerId,
        error: error instanceof Error ? error.message : String(error),
      });
      return null;
    }
  }

  async set(ownerId: string, memory: string): Promise<void> {
    try {
      const client = await this.ensureClient();
      if (this.ttl > 0) {
        await client.set(this.key(ownerId), memory, { EX: this.ttl });
      } else {
        await client.set(this.key(ownerId), memory);
      }
    } catch (error) {
      logger.error('Redis set failed', {
        ownerId,
        error: error instanceof Error ? error.message : String(error),
      });
    }
  }

  async delete(ownerId: string): Promise<void> {
    try {
      const client = await this.ensureClient();
      await client.del(this.key(ownerId));
    } catch (error) {
      logger.error('Redis delete failed', {
        ownerId,
        error: error instanceof Error ? error.message : String(error),
      });
    }
  }

  async close(): Promise<void> {
    try {
      if (this.client) {
        await this.client.quit();
        this.client = null;
        logger.info('Redis storage closed');
      }
    } catch (error) {
      logger.error('Redis close failed', {
        error: error instanceof Error ? error.message : String(error),
      });
      this.client = null;
    }
  }
}

import type { CustomStorageConfig, StorageBackend } from '../types';
import { logger } from '../logger';

/**
 * Custom storage backend that delegates all operations to consumer-provided callbacks.
 *
 * The consumer is responsible for the actual persistence — Hippocampus only
 * calls the provided onGet/onSet/onDelete/onClose functions.
 *
 * TypeScript enforces that onGet/onSet/onDelete are functions via CustomStorageConfig.
 * No runtime validation needed — the type system handles it at compile time.
 */
export class CustomStorage implements StorageBackend {
  private readonly config: CustomStorageConfig;

  constructor(config: CustomStorageConfig) {
    this.config = config;
    logger.info('Custom storage backend initialized');
  }

  async get(ownerId: string): Promise<string | null> {
    return this.config.onGet(ownerId);
  }

  async set(ownerId: string, memory: string): Promise<void> {
    return this.config.onSet(ownerId, memory);
  }

  async delete(ownerId: string): Promise<void> {
    return this.config.onDelete(ownerId);
  }

  async close(): Promise<void> {
    if (this.config.onClose) {
      return this.config.onClose();
    }
  }
}

import type { StorageBackend, SqliteStorageConfig } from '../types';
import { logger } from '../logger';
import path from 'path';
import fs from 'fs';
import { createRequire } from 'module';

export class SqliteStorage implements StorageBackend {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  private db: any = null;
  private dbPath: string;

  constructor(config?: SqliteStorageConfig) {
    this.dbPath = config?.path || path.join(process.cwd(), 'data', 'hippocampus.sqlite');
  }

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  private ensureDb(): any {
    if (this.db) {
      return this.db;
    }

    try {
      // Ensure parent directory exists
      const dir = path.dirname(this.dbPath);
      if (!fs.existsSync(dir)) {
        fs.mkdirSync(dir, { recursive: true });
      }

      const require = createRequire(import.meta.url);
      const Database = require('better-sqlite3');
      this.db = new Database(this.dbPath);

      this.db.pragma('journal_mode = WAL');

      this.db.exec(`
        CREATE TABLE IF NOT EXISTS memories (
          owner_id TEXT PRIMARY KEY,
          memory TEXT NOT NULL,
          updated_at TEXT NOT NULL DEFAULT (datetime('now'))
        )
      `);

      logger.info('SQLite storage initialized', { path: this.dbPath });
    } catch (error) {
      logger.error('Failed to initialize SQLite storage', {
        path: this.dbPath,
        error: error instanceof Error ? error.message : String(error),
      });
      throw error;
    }

    return this.db;
  }

  async get(ownerId: string): Promise<string | null> {
    try {
      const db = this.ensureDb();
      const row = db.prepare('SELECT memory FROM memories WHERE owner_id = ?').get(ownerId) as
        | { memory: string }
        | undefined;
      return row?.memory ?? null;
    } catch (error) {
      logger.error('SQLite get failed', {
        ownerId,
        error: error instanceof Error ? error.message : String(error),
      });
      return null;
    }
  }

  async set(ownerId: string, memory: string): Promise<void> {
    try {
      const db = this.ensureDb();
      db.prepare(
        `INSERT INTO memories (owner_id, memory, updated_at) VALUES (?, ?, datetime('now'))
         ON CONFLICT(owner_id) DO UPDATE SET memory = excluded.memory, updated_at = excluded.updated_at`
      ).run(ownerId, memory);
    } catch (error) {
      logger.error('SQLite set failed', {
        ownerId,
        error: error instanceof Error ? error.message : String(error),
      });
    }
  }

  async delete(ownerId: string): Promise<void> {
    try {
      const db = this.ensureDb();
      db.prepare('DELETE FROM memories WHERE owner_id = ?').run(ownerId);
    } catch (error) {
      logger.error('SQLite delete failed', {
        ownerId,
        error: error instanceof Error ? error.message : String(error),
      });
    }
  }

  async close(): Promise<void> {
    try {
      if (this.db) {
        this.db.close();
        this.db = null;
        logger.info('SQLite storage closed');
      }
    } catch (error) {
      logger.error('SQLite close failed', {
        error: error instanceof Error ? error.message : String(error),
      });
      this.db = null;
    }
  }
}

import type { StorageBackend, S3StorageConfig } from '../types';
import { logger } from '../logger';

export class S3Storage implements StorageBackend {
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  private s3: any = null;
  private bucket: string;
  private prefix: string;

  constructor(config: S3StorageConfig) {
    this.bucket = config.bucket;
    this.prefix = config.prefix || 'hippocampus/memories/';

    // Ensure prefix ends with /
    if (this.prefix && !this.prefix.endsWith('/')) {
      this.prefix += '/';
    }
  }

  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  private async ensureClient(): Promise<any> {
    if (this.s3) {
      return this.s3;
    }

    const { S3Client } = await import('@aws-sdk/client-s3');
    this.s3 = new S3Client({});

    logger.info('S3 storage initialized', {
      bucket: this.bucket,
      prefix: this.prefix,
    });
    return this.s3;
  }

  private objectKey(ownerId: string): string {
    return `${this.prefix}${ownerId}`;
  }

  async get(ownerId: string): Promise<string | null> {
    try {
      const s3 = await this.ensureClient();
      const { GetObjectCommand } = await import('@aws-sdk/client-s3');

      const response = await s3.send(
        new GetObjectCommand({
          Bucket: this.bucket,
          Key: this.objectKey(ownerId),
        })
      );
      return (await response.Body?.transformToString('utf-8')) ?? null;
    } catch (error: unknown) {
      // NoSuchKey = ownerId not found — not an error
      if (error && typeof error === 'object' && 'name' in error && error.name === 'NoSuchKey') {
        return null;
      }
      logger.error('S3 get failed', {
        ownerId,
        bucket: this.bucket,
        error: error instanceof Error ? error.message : String(error),
      });
      return null;
    }
  }

  async set(ownerId: string, memory: string): Promise<void> {
    try {
      const s3 = await this.ensureClient();
      const { PutObjectCommand } = await import('@aws-sdk/client-s3');

      await s3.send(
        new PutObjectCommand({
          Bucket: this.bucket,
          Key: this.objectKey(ownerId),
          Body: memory,
          ContentType: 'text/plain; charset=utf-8',
        })
      );
    } catch (error) {
      logger.error('S3 set failed', {
        ownerId,
        bucket: this.bucket,
        error: error instanceof Error ? error.message : String(error),
      });
    }
  }

  async delete(ownerId: string): Promise<void> {
    try {
      const s3 = await this.ensureClient();
      const { DeleteObjectCommand } = await import('@aws-sdk/client-s3');

      await s3.send(
        new DeleteObjectCommand({
          Bucket: this.bucket,
          Key: this.objectKey(ownerId),
        })
      );
    } catch (error) {
      logger.error('S3 delete failed', {
        ownerId,
        bucket: this.bucket,
        error: error instanceof Error ? error.message : String(error),
      });
    }
  }

  async close(): Promise<void> {
    try {
      if (this.s3) {
        this.s3.destroy?.();
        this.s3 = null;
        logger.info('S3 storage closed');
      }
    } catch (error) {
      logger.error('S3 close failed', {
        error: error instanceof Error ? error.message : String(error),
      });
      this.s3 = null;
    }
  }
}

import typescript from '@rollup/plugin-typescript';
import { nodeResolve } from '@rollup/plugin-node-resolve';
import replace from '@rollup/plugin-replace';
import packageJson from './package.json' with { type: 'json' };

