/**
 * Post-build script: adds .js extensions to relative imports in compiled output.
 * This allows TypeScript source to use clean extensionless imports while
 * producing Node.js ESM-compatible output.
 */
import { readdir, readFile, writeFile } from 'node:fs/promises';
import { join } from 'node:path';

const DIST = new URL('../dist', import.meta.url).pathname;

const RELATIVE_IMPORT = /(from\s+['"])(\.\.?\/[^'"]*?)(['"])/g;

async function fixFile(filePath) {
  const content = await readFile(filePath, 'utf-8');
  const fixed = content.replace(RELATIVE_IMPORT, (match, pre, specifier, post) => {
    if (specifier.endsWith('.js') || specifier.endsWith('.json')) return match;
    return `${pre}${specifier}.js${post}`;
  });
  if (fixed !== content) {
    await writeFile(filePath, fixed, 'utf-8');
  }
}

const files = await readdir(DIST);
for (const file of files) {
  if (file.endsWith('.js') || file.endsWith('.d.ts')) {
    await fixFile(join(DIST, file));
  }
}

export { Hippocampus } from './client';
export { logger } from './logger';
export type { LogLevel } from './logger';
export type {
  StorageType,
  StorageBackend,
  StorageConfig,
  SqliteStorageConfig,
  RedisStorageConfig,
  S3StorageConfig,
  CustomStorageConfig,
  HippocampusConfig,
  AddOptions,
  CondenserGenerateOptions,
  CondenserGenerateResult,
  CondenserInstance,
} from './types';

export { SqliteStorage } from './storage/sqlite';
export { RedisStorage } from './storage/redis';
export { S3Storage } from './storage/s3';
export { CustomStorage } from './storage/custom';

import type { AddOptions, CondenserInstance, HippocampusConfig, StorageBackend, StorageConfig } from './types';
import { logger } from './logger';

const DEFAULT_PROMPT = `You are a memory condensation engine. You receive:
1. OLD_MEMORY: the user's existing memory summary (may be empty)
2. NEW_CONTENT: new conversation content

Your job: merge the old memory with relevant new information into a single condensed summary.

Rules:
- Output ONLY the condensed memory text, nothing else
- Maximum {{MAX_WORDS}} words
- Preserve important facts: names, preferences, goals, decisions, context
- Drop greetings, filler, redundant information
- If NEW_CONTENT has nothing worth remembering, return OLD_MEMORY unchanged
- If OLD_MEMORY is empty and NEW_CONTENT has nothing worth remembering, return empty string

OLD_MEMORY:
{{OLD_MEMORY}}

NEW_CONTENT:
{{NEW_CONTENT}}

Condensed memory:`;
export class Hippocampus {
  private storage: StorageBackend | null = null;
  private storageConfig: StorageConfig;
  private prompt: string;
  private maxWords: number;
  private neurolink: CondenserInstance | null = null;
  private config: HippocampusConfig;

  constructor(config: HippocampusConfig = {}) {
    this.config = config;
    this.storageConfig = config.storage || { type: 'sqlite' };
    this.prompt = config.prompt || process.env.HC_CONDENSATION_PROMPT || DEFAULT_PROMPT;
    this.maxWords = config.maxWords || 50;

    logger.info('Hippocampus initialized', {
      storage: this.storageConfig.type,
      maxWords: this.maxWords,
    });
  }

  private async ensureStorage(): Promise<StorageBackend | null> {
    if (this.storage) {
      return this.storage;
    }

    try {
      switch (this.storageConfig.type) {
        case 'sqlite': {
          const { SqliteStorage } = await import('./storage/sqlite');
          this.storage = new SqliteStorage(this.storageConfig);
          break;
        }
        case 'redis': {
          const { RedisStorage } = await import('./storage/redis');
          this.storage = new RedisStorage(this.storageConfig);
          break;
        }
        case 's3': {
          const { S3Storage } = await import('./storage/s3');
          this.storage = new S3Storage(this.storageConfig);
          break;
        }
        case 'custom': {
          const { CustomStorage } = await import('./storage/custom');
          this.storage = new CustomStorage(this.storageConfig);
          break;
        }
        default:
          logger.error('Unknown storage type', {
            type: (this.storageConfig as { type: string }).type,
          });
          return null;
      }
    } catch (error) {
      logger.error('Failed to initialize storage backend', {
        type: this.storageConfig.type,
        error: error instanceof Error ? error.message : String(error),
      });
      return null;
    }

    return this.storage;
  }

  private async ensureNeurolink(): Promise<CondenserInstance | null> {
    if (this.neurolink) {
      return this.neurolink;
    }

    const supplied = this.config.neurolink?.instance;
    if (supplied) {
      this.neurolink = supplied;
      logger.info('Using host-supplied instance for Hippocampus condensation');
      return this.neurolink;
    }

    try {
      const { NeuroLink } = await import('@juspay/neurolink');
      const credentials = this.config.neurolink?.credentials;
      // The constructor options type belongs to whichever NeuroLink the host
      // installed; only `credentials` is forwarded, and only when given.
      const options = (credentials ? { credentials } : undefined) as ConstructorParameters<typeof NeuroLink>[0];
      this.neurolink = new NeuroLink(options);
      logger.info('NeuroLink instance created for Hippocampus condensation', {
        withCredentials: credentials !== undefined,
      });
      return this.neurolink;
    } catch (error) {
      logger.error('Failed to initialize NeuroLink for condensation', {
        error: error instanceof Error ? error.message : String(error),
      });
      return null;
    }
  }

  /**
   * Add/update memory for an owner.
   *
   * Fetches existing memory, merges with new content via LLM, stores result.
   *
   * @param ownerId - Unique identifier (user ID, session ID, etc.)
   * @param content - New conversation content to incorporate
   * @param options - Optional per-call overrides for prompt and maxWords
   * @returns The condensed memory string that was stored, or empty string on failure
   */
  async add(ownerId: string, content: string, options?: AddOptions): Promise<string> {
    try {
      const storage = await this.ensureStorage();
      if (!storage) {
        return '';
      }

      const neurolink = await this.ensureNeurolink();
      if (!neurolink) {
        return '';
      }

      let oldMemory = '';
      try {
        oldMemory = (await storage.get(ownerId)) || '';
      } catch (error) {
        logger.warn('Failed to fetch existing memory, proceeding without it', {
          ownerId,
          error: error instanceof Error ? error.message : String(error),
        });
      }

      const effectivePrompt = options?.prompt || this.prompt;
      const effectiveMaxWords = options?.maxWords || this.maxWords;

      const filledPrompt = effectivePrompt
        // Function replacers substitute literally. A string replacer
        // interprets `$&`, `$'`, `$\`` and `$n` in user content, so a message
        // containing "$&" would re-insert the placeholder into the prompt.
        .replaceAll('{{OLD_MEMORY}}', () => oldMemory || '(none)')
        .replaceAll('{{NEW_CONTENT}}', () => content)
        .replaceAll('{{MAX_WORDS}}', () => String(effectiveMaxWords));

      logger.debug('Condensing memory Request', {
        ownerId,
        oldMemory: oldMemory,
        oldMemoryLength: oldMemory.length,
        newContentLength: content.length,
        customPrompt: !!options?.prompt,
        maxWords: effectiveMaxWords,
      });

      let condensed = '';
      try {
        const result = await neurolink.generate({
          input: { text: filledPrompt },
          provider: this.config.neurolink?.provider,
          model: this.config.neurolink?.model,
          temperature: this.config.neurolink?.temperature ?? 0.1,
          disableTools: true,
        });
        condensed = (result?.content || '').trim();
      } catch (error) {
        logger.error('LLM condensation call failed', {
          ownerId,
          error: error instanceof Error ? error.message : String(error),
        });
        return oldMemory;
      }

      if (condensed) {
        try {
          await storage.set(ownerId, condensed);
          logger.info('Memory updated', { ownerId, words: condensed.split(/\s+/).length, newMemory: condensed });
        } catch (error) {
          logger.error('Failed to persist condensed memory', {
            ownerId,
            error: error instanceof Error ? error.message : String(error),
          });
        }
      } else if (oldMemory) {
        logger.debug('No new memory extracted, keeping existing', { ownerId });
      }

      return condensed || oldMemory;
    } catch (error) {
      logger.error('Unexpected error in add()', {
        ownerId,
        error: error instanceof Error ? error.message : String(error),
      });
      return '';
    }
  }

  /**
   * Get the stored memory for an owner.
   *
   * @param ownerId - Unique identifier
   * @returns The condensed memory string, or null if none exists or on failure
   */
  async get(ownerId: string): Promise<string | null> {
    try {
      const storage = await this.ensureStorage();
      if (!storage) {
        return null;
      }
      return await storage.get(ownerId);
    } catch (error) {
      logger.error('Failed to get memory', {
        ownerId,
        error: error instanceof Error ? error.message : String(error),
      });
      return null;
    }
  }

  /**
   * Delete memory for an owner.
   *
   * @param ownerId - Unique identifier
   */
  async delete(ownerId: string): Promise<void> {
    try {
      const storage = await this.ensureStorage();
      if (!storage) {
        return;
      }
      await storage.delete(ownerId);
      logger.info('Memory deleted', { ownerId });
    } catch (error) {
      logger.error('Failed to delete memory', {
        ownerId,
        error: error instanceof Error ? error.message : String(error),
      });
    }
  }

  /**
   * Close storage connections and clean up resources.
   */
  async close(): Promise<void> {
    try {
      if (this.storage) {
        await this.storage.close();
        this.storage = null;
      }
      logger.info('Hippocampus closed');
    } catch (error) {
      logger.error('Failed to close Hippocampus', {
        error: error instanceof Error ? error.message : String(error),
      });
      this.storage = null;
    }
  }
}

/** Storage backend type */
export type StorageType = 'sqlite' | 'redis' | 's3' | 'custom';

export interface StorageBackend {
  get(ownerId: string): Promise<string | null>;
  set(ownerId: string, memory: string): Promise<void>;
  delete(ownerId: string): Promise<void>;
  close(): Promise<void>;
}

export interface SqliteStorageConfig {
  type: 'sqlite';
  /** Path to SQLite file. Default: ./data/hippocampus.sqlite */
  path?: string;
}

export interface RedisStorageConfig {
  type: 'redis';
  host?: string;
  port?: number;
  password?: string;
  db?: number;
  keyPrefix?: string;
  ttl?: number;
}

/** S3 storage config */
export interface S3StorageConfig {
  type: 's3';
  bucket: string;
  prefix?: string;
}

export interface CustomStorageConfig {
  type: 'custom';
  onGet: (ownerId: string) => Promise<string | null>;
  onSet: (ownerId: string, memory: string) => Promise<void>;
  onDelete: (ownerId: string) => Promise<void>;
  onClose?: () => Promise<void>;
}

export type StorageConfig = SqliteStorageConfig | RedisStorageConfig | S3StorageConfig | CustomStorageConfig;

/** The request Hippocampus sends to the condenser's `generate()`. */
export interface CondenserGenerateOptions {
  input: { text: string };
  provider?: string;
  model?: string;
  temperature?: number;
  disableTools?: boolean;
}

/** The only field Hippocampus reads back from a condensation call. */
export interface CondenserGenerateResult {
  content?: string;
}

/**
 * Anything with a `generate()` Hippocampus can condense through — a
 * `NeuroLink` instance satisfies this structurally, and so does a host stub.
 */
export interface CondenserInstance {
  generate(options: CondenserGenerateOptions): Promise<CondenserGenerateResult | null | undefined>;
}

export interface HippocampusConfig {
  storage?: StorageConfig;
  prompt?: string;
  neurolink?: {
    provider?: string;
    model?: string;
    temperature?: number;
    /**
     * Credentials for the NeuroLink instance Hippocampus constructs for
     * condensation (`new NeuroLink({ credentials })`). Same shape as
     * NeuroLink's `NeurolinkCredentials`; typed loosely so this package does
     * not depend on NeuroLink's types. Ignored when `instance` is set.
     */
    credentials?: Record<string, unknown>;
    /**
     * Host-supplied condenser. When set, Hippocampus never constructs its own
     * NeuroLink and routes every condensation call through this object.
     */
    instance?: CondenserInstance;
  };
  maxWords?: number;
}

export interface AddOptions {
  prompt?: string;
  maxWords?: number;
}

export type LogLevel = 'debug' | 'info' | 'warn' | 'error';

const ALL_LEVELS: LogLevel[] = ['debug', 'info', 'warn', 'error'];

function parseLogLevels(input: string): Set<LogLevel> {
  const trimmed = input.trim().toLowerCase();

  if (trimmed === 'off' || trimmed === '') {
    return new Set();
  }

  const levels = trimmed
    .split(',')
    .map((s) => s.trim())
    .filter(Boolean);
  return new Set(levels.filter((l) => ALL_LEVELS.includes(l as LogLevel)) as LogLevel[]);
}

let enabledLevels: Set<LogLevel> | null = null;

function getEnabledLevels(): Set<LogLevel> {
  if (enabledLevels === null) {
    enabledLevels = parseLogLevels(process.env.HC_LOG_LEVEL || 'off');
  }
  return enabledLevels;
}

function shouldLog(level: LogLevel): boolean {
  return getEnabledLevels().has(level);
}

function formatMessage(level: LogLevel, message: string, context?: Record<string, unknown>): string {
  const timestamp = new Date().toISOString();
  const base = `[${timestamp}] [HIPPOCAMPUS@__VERSION__] [${level.toUpperCase()}] ${message}`;
  if (context && Object.keys(context).length > 0) {
    return `${base} ${JSON.stringify(context)}`;
  }
  return base;
}

export const logger = {
  /**
   * Programmatically override which log levels are active.
   * Pass an array of levels or `'off'` to disable all logging.
   */
  setLevels(levels: LogLevel[] | 'off') {
    enabledLevels = levels === 'off' ? new Set<LogLevel>() : new Set(levels);
  },

  debug(message: string, context?: Record<string, unknown>) {
    if (shouldLog('debug')) {
      console.debug(formatMessage('debug', message, context));
    }
  },

  info(message: string, context?: Record<string, unknown>) {
    if (shouldLog('info')) {
      console.info(formatMessage('info', message, context));
    }
  },

  warn(message: string, context?: Record<string, unknown>) {
    if (shouldLog('warn')) {
      console.warn(formatMessage('warn', message, context));
    }
  },

  error(message: string, context?: Record<string, unknown>) {
    if (shouldLog('error')) {
      console.error(formatMessage('error', message, context));
    }
  },
};

# Hippocampus

Embedded memory SDK for AI applications. Maintains a condensed, per-user memory summary that persists across conversations using LLM-powered condensation.

Each user gets a single memory string (keyed by `ownerId`) that is progressively condensed as new information arrives. Old memory + new content are merged by an LLM into a tight summary within a configurable word limit.

| Package | npm | Description |
|---------|-----|-------------|
| [sdk](./sdk) | [`@juspay/hippocampus`](https://www.npmjs.com/package/@juspay/hippocampus) | Embedded memory SDK — LLM-powered condensed key-value memory |

## Installation

```bash
pnpm add @juspay/hippocampus
```

Peer dependencies:

```bash
# Required — LLM provider for memory condensation
pnpm add @juspay/neurolink

# Optional — only if using SQLite storage
pnpm add better-sqlite3
```

## Quick Start

```typescript
import { Hippocampus } from '@juspay/hippocampus';

const memory = new Hippocampus({
  storage: { type: 'sqlite' },
  neurolink: { provider: 'google-ai', model: 'gemini-2.5-flash' },
  maxWords: 50,
});

// Store a conversation turn — LLM condenses it automatically
await memory.add('user-123', 'User: My name is Alice\nAssistant: Nice to meet you, Alice!');

// Retrieve the condensed memory
const summary = await memory.get('user-123');
// → "User's name is Alice."

// Next conversation — old memory is merged with new content
await memory.add('user-123', 'User: I run a Shopify store\nAssistant: Great, I can help with that!');
const updated = await memory.get('user-123');
// → "Alice runs a Shopify store."

// Cleanup
await memory.close();
```

## How It Works

```
memory.add(ownerId, newContent)
       │
       ▼
 ┌──────────────────┐
 │ storage.get()    │  ← Fetch existing condensed memory for this owner
 └───────┬──────────┘
         │
         ▼
 ┌──────────────────┐
 │ LLM condensation │  ← Merge old memory + new content into a summary
 └───────┬──────────┘     (via @juspay/neurolink)
         │
         ▼
 ┌──────────────────┐
 │ storage.set()    │  ← Persist the new condensed memory
 └──────────────────┘
```

The condensation prompt instructs the LLM to:
- Keep important facts: names, preferences, goals, decisions
- Drop greetings, filler, and redundant information
- Stay within the `maxWords` limit
- Return the old memory unchanged if there is nothing new worth remembering

## Storage Backends

Hippocampus supports 4 storage backends. Backend modules are dynamically imported at runtime — code paths for unused backends are never loaded. SQLite requires `better-sqlite3` as an optional peer dependency; Redis and S3 ship their clients bundled.

### SQLite (Default)

Good for local development and single-server deployments.

```typescript
const memory = new Hippocampus({
  storage: {
    type: 'sqlite',
    path: './data/hippocampus.sqlite', // optional, this is the default
  },
});
```

Requires the `better-sqlite3` peer dependency:

```bash
pnpm add better-sqlite3
```

Creates a `memories` table automatically with WAL journal mode.

### Redis

Good for distributed deployments where multiple servers share state.

```typescript
const memory = new Hippocampus({
  storage: {
    type: 'redis',
    host: 'localhost', // default, also reads REDIS_HOST env
    port: 6379, // default, also reads REDIS_PORT env
    password: undefined, // also reads REDIS_PASSWORD env
    db: 0, // also reads REDIS_DB env
    keyPrefix: 'hippocampus:memory:', // default key prefix
    ttl: 0, // seconds, 0 = no expiry
  },
});
```

### S3

Good for production deployments on AWS. Each user's memory is stored as a single S3 object.

```typescript
const memory = new Hippocampus({
  storage: {
    type: 's3',
    bucket: 'my-bucket', // required
    prefix: 'hippocampus/memories/', // optional, default prefix
  },
});
```

Uses the default AWS SDK credential chain (`AWS_ACCESS_KEY_ID`, IAM role, etc.).

Storage path: `s3://{bucket}/{prefix}{ownerId}`

### Custom (Consumer-Managed)

Delegates storage entirely to your application via callbacks. Use this when you want to manage persistence yourself — call your own API, write to your own database, or integrate with any external system.

```typescript
const memory = new Hippocampus({
  storage: {
    type: 'custom',
    onGet: async (ownerId) => {
      // Called when Hippocampus needs the existing memory
      return await myDB.getMemory(ownerId);
    },
    onSet: async (ownerId, memory) => {
      // Called when Hippocampus has a new condensed memory to persist
      await myDB.saveMemory(ownerId, memory);
    },
    onDelete: async (ownerId) => {
      // Called when memory.delete() is invoked
      await myDB.deleteMemory(ownerId);
    },
    onClose: async () => {
      // Optional — called on memory.close() for cleanup
      await myDB.disconnect();
    },
  },
});
```

| Callback   | Required | Signature                                             | Description                        |
| ---------- | -------- | ----------------------------------------------------- | ---------------------------------- |
| `onGet`    | Yes      | `(ownerId: string) => Promise<string \| null>`        | Retrieve stored memory for owner   |
| `onSet`    | Yes      | `(ownerId: string, memory: string) => Promise<void>`  | Persist condensed memory for owner |
| `onDelete` | Yes      | `(ownerId: string) => Promise<void>`                  | Delete memory for owner            |
| `onClose`  | No       | `() => Promise<void>`                                 | Cleanup on close                   |

Example — file-based custom storage:

```typescript
import { readFile, writeFile, unlink, mkdir } from 'node:fs/promises';
import { join } from 'node:path';

const dir = './data/memory';

const memory = new Hippocampus({
  storage: {
    type: 'custom',
    onGet: async (ownerId) => {
      try {
        return await readFile(join(dir, `${ownerId}.txt`), 'utf-8');
      } catch {
        return null;
      }
    },
    onSet: async (ownerId, memory) => {
      await mkdir(dir, { recursive: true });
      await writeFile(join(dir, `${ownerId}.txt`), memory, 'utf-8');
    },
    onDelete: async (ownerId) => {
      try {
        await unlink(join(dir, `${ownerId}.txt`));
      } catch {
        // file may not exist
      }
    },
  },
});
```

## API Reference

### `new Hippocampus(config?)`

Creates a new Hippocampus instance.

```typescript
interface HippocampusConfig {
  storage?: StorageConfig; // Default: { type: 'sqlite' }
  prompt?: string; // Custom condensation prompt
  neurolink?: {
    provider?: string; // LLM provider (e.g. 'google-ai', 'openai')
    model?: string; // Model name (e.g. 'gemini-2.5-flash')
    temperature?: number; // Default: 0.1
    credentials?: Record<string, unknown>; // Passed to `new NeuroLink({ credentials })`
    instance?: CondenserInstance; // Host-supplied condenser; skips constructing NeuroLink
  };
  maxWords?: number; // Default: 50
}
```

By default Hippocampus constructs its own `NeuroLink` for condensation, so
provider keys come from the environment. Pass `neurolink.credentials` (the same
shape as NeuroLink's `NeurolinkCredentials`) to hand it keys from a vault
instead, or `neurolink.instance` — anything with a
`generate({ input: { text } }) => Promise<{ content?: string }>` — to route
condensation through an instance the host already owns. `instance` wins over
`credentials`.

### `memory.add(ownerId, content, options?): Promise<string>`

Fetches existing memory, condenses it with new content via LLM, and stores the result.

- **ownerId** — Unique identifier (user ID, session ID, etc.)
- **content** — New conversation content to incorporate
- **options.prompt** — Per-call condensation prompt override (must include `{{OLD_MEMORY}}`, `{{NEW_CONTENT}}`, `{{MAX_WORDS}}` placeholders)
- **options.maxWords** — Per-call max words override
- **Returns** — The condensed memory on success. Falls back to the previously stored memory if the LLM call fails. Returns empty string only when storage or NeuroLink cannot be initialized.

When `options` is omitted, the constructor-level `prompt` and `maxWords` are used.

### `memory.get(ownerId): Promise<string | null>`

Retrieves the stored condensed memory for an owner.

- **Returns** — The memory string, or `null` if none exists

### `memory.delete(ownerId): Promise<void>`

Deletes the stored memory for an owner.

### `memory.close(): Promise<void>`

Closes storage connections and releases resources.

## Custom Condensation Prompt

Override the default prompt using the `prompt` config field or the `HC_CONDENSATION_PROMPT` environment variable:

```typescript
const memory = new Hippocampus({
  prompt: `Merge the old memory with new facts. Maximum {{MAX_WORDS}} words.

OLD_MEMORY:
{{OLD_MEMORY}}

NEW_CONTENT:
{{NEW_CONTENT}}

Condensed memory:`,
  maxWords: 100,
});
```

Available placeholders:

| Placeholder       | Replaced With                                              |
| ----------------- | ---------------------------------------------------------- |
| `{{OLD_MEMORY}}`  | The user's existing condensed memory (or `"(none)"`)       |
| `{{NEW_CONTENT}}` | The new conversation content                               |
| `{{MAX_WORDS}}`   | The configured `maxWords` value                            |

### Per-Call Overrides

The `add()` method accepts an optional `options` parameter to override `prompt` and `maxWords` for a specific call. This is useful when a single Hippocampus instance manages different memory scopes that need different condensation strategies.

```typescript
// Personal user memory — uses constructor defaults
await memory.add('user-alice', conversation);

// Org-level policy memory — custom prompt, higher word limit
await memory.add('org-acme', conversation, {
  prompt: `Extract only compliance requirements, security policies, and org decisions.

OLD_MEMORY:
{{OLD_MEMORY}}

NEW_CONTENT:
{{NEW_CONTENT}}

Condensed memory (max {{MAX_WORDS}} words):`,
  maxWords: 100,
});

// Team context — just a higher word limit
await memory.add('team-payments', conversation, { maxWords: 75 });
```

## Usage with NeuroLink

When used through `@juspay/neurolink`, memory is automatically retrieved before each LLM call and stored after:

```typescript
import { NeuroLink } from '@juspay/neurolink';

const neurolink = new NeuroLink({
  conversationMemory: {
    enabled: true,
    memory: {
      enabled: true,
      storage: {
        type: 'custom',
        onGet: async (ownerId) => await myDB.getMemory(ownerId),
        onSet: async (ownerId, memory) => await myDB.saveMemory(ownerId, memory),
        onDelete: async (ownerId) => await myDB.deleteMemory(ownerId),
      },
      neurolink: { provider: 'google-ai', model: 'gemini-2.5-flash' },
      maxWords: 50,
    },
  },
});

// Memory is automatically managed on each call
const result = await neurolink.generate({
  input: { text: 'My name is Alice' },
  context: { userId: 'user-123' },
});
```

